package cyan.project.twinkle.admin;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import cyan.project.twinkle.repository.ProductRepository;
import cyan.project.twinkle.service.PricingService;
import java.util.*;
import java.time.LocalDateTime;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class AdminQueryService {
 private final JdbcTemplate sql;private final AdminContextService context;private final ProductRepository products;private final PricingService pricing;
 public record Page(List<Map<String,Object>> items,long total,int page,int size){}
 public record Source(String select,String from,String search,String status,String store,String key){}
 private Source source(String area){return switch(area){
  case "users"->new Source("t.email AS id,t.email,t.username,t.full_name,t.phone,t.is_enabled,t.created_at,t.updated_at,(SELECT STRING_AGG(r.name,',') FROM USER_ROLES ur JOIN ROLES r ON r.id=ur.role_id WHERE ur.user_email=t.email) AS roles,(SELECT STRING_AGG(s.name,',') FROM STORES s WHERE s.manager_email=t.email OR EXISTS(SELECT 1 FROM STORE_STAFF_ASSIGNMENTS a WHERE a.store_id=s.store_id AND a.user_email=t.email AND a.active=1)) AS assigned_store","USERS t","CONCAT(t.email,' ',t.full_name)","CASE WHEN t.is_enabled=1 THEN 'ACTIVE' ELSE 'INACTIVE' END",null,"t.email");
  case "stores"->new Source("t.store_id AS id,t.*,u.is_enabled AS manager_enabled,(SELECT COUNT(*) FROM STORE_INVENTORY i WHERE i.store_id=t.store_id) AS inventory_count,(SELECT COUNT(DISTINCT i.order_id) FROM ORDER_ITEMS i WHERE i.store_id=t.store_id) AS order_count","STORES t LEFT JOIN USERS u ON u.email=t.manager_email","t.name","t.status","t.store_id","t.store_id");
  case "categories"->new Source("t.*,(SELECT COUNT(*) FROM PRODUCTS p WHERE p.category_id=t.id) AS product_count","CATEGORIES t","t.name","t.status",null,"t.id");
  case "brands"->new Source("t.*,(SELECT COUNT(*) FROM PRODUCTS p WHERE p.brand_id=t.id) AS product_count","BRANDS t","t.name",null,null,"t.id");
  case "products"->new Source("t.*,b.name AS brand,c.name AS category,(SELECT COUNT(*) FROM PRODUCT_VARIANTS v WHERE v.product_id=t.id) AS variant_count,(SELECT COUNT(DISTINCT si.store_id) FROM STORE_INVENTORY si JOIN PRODUCT_VARIANTS v ON v.id=si.variant_id WHERE v.product_id=t.id) AS store_count","PRODUCTS t JOIN BRANDS b ON b.id=t.brand_id JOIN CATEGORIES c ON c.id=t.category_id","CONCAT(t.name,' ',t.slug)","t.status",null,"t.id");
  case "variants"->new Source("t.*,p.name AS product,(SELECT COUNT(*) FROM STORE_INVENTORY si WHERE si.variant_id=t.id) AS inventory_count","PRODUCT_VARIANTS t JOIN PRODUCTS p ON p.id=t.product_id","CONCAT(t.sku,' ',p.name)","t.status",null,"t.id");
  case "inventory"->new Source("CONCAT(t.store_id,':',t.variant_id) AS id,t.*,s.name AS store,v.sku,v.size,v.color,p.name AS product,CASE WHEN t.quantity=0 THEN 'OUT' WHEN t.quantity<=t.reorder_level THEN 'LOW' ELSE 'AVAILABLE' END AS status,(SELECT COUNT(*) FROM INVENTORY_RESTOCK_REQUESTS r WHERE r.store_id=t.store_id AND r.variant_id=t.variant_id AND r.status='PENDING') AS pending_requests","STORE_INVENTORY t JOIN STORES s ON s.store_id=t.store_id JOIN PRODUCT_VARIANTS v ON v.id=t.variant_id JOIN PRODUCTS p ON p.id=v.product_id","CONCAT(v.sku,' ',p.name)","CASE WHEN t.quantity=0 THEN 'OUT' WHEN t.quantity<=t.reorder_level THEN 'LOW' ELSE 'AVAILABLE' END","t.store_id","t.store_id,t.variant_id");
  case "orders"->new Source("t.*,p.status AS payment_status,CASE WHEN t.status=N'Chờ xác nhận đơn hàng' AND t.payment_method='BANKING' AND COALESCE(p.status,'PENDING')<>'PAID' THEN N'Chờ xác nhận thanh toán' ELSE t.status END AS display_status","ORDERS t LEFT JOIN PAYMENTS p ON p.order_id=t.id","t.order_code","t.status","EXISTS_ORDER","t.id");
  case "catalog-requests"->new Source("t.*,s.name AS store","CATALOG_CHANGE_REQUESTS t JOIN STORES s ON s.store_id=t.store_id","CONCAT(t.reason,' ',t.requester_email)","t.status","t.store_id","t.id");
  case "restock-requests"->new Source("t.*,s.name AS store,v.sku","INVENTORY_RESTOCK_REQUESTS t JOIN STORES s ON s.store_id=t.store_id JOIN PRODUCT_VARIANTS v ON v.id=t.variant_id","CONCAT(t.reason,' ',v.sku)","t.status","t.store_id","t.id");
  case "inventory-movements"->new Source("t.*,s.name AS store,v.sku","INVENTORY_MOVEMENTS t JOIN STORES s ON s.store_id=t.store_id JOIN PRODUCT_VARIANTS v ON v.id=t.variant_id","CONCAT(t.reason,' ',v.sku)","t.movement_type","t.store_id","t.id");
  case "promotions"->new Source("t.*","PROMOTIONS t","t.name","t.status",null,"t.id");
  case "coupons"->new Source("t.*","COUPONS t","CONCAT(t.code,' ',t.name)","CASE WHEN t.is_active=1 THEN 'ACTIVE' ELSE 'INACTIVE' END",null,"t.id");
  case "audit"->new Source("t.*","ADMIN_AUDIT_LOG t","CONCAT(t.action_type,' ',t.summary)",null,null,"t.id");
  default->throw new IllegalArgumentException("Unknown area");};}
 public Page list(String area,int page,int size,String search,String status,Integer store,String sort,String direction,String role,String method,String paymentStatus,String fromDate,String toDate,String requestType){context.actor();if(page<0||page>1000000||size<1||size>100||search.length()>150)throw new IllegalArgumentException();size=30;var s=source(area);String where=" WHERE "+s.search()+" LIKE ?";var args=new ArrayList<Object>();args.add("%"+search+"%");
  if(!status.isBlank()&&s.status()!=null){where+=" AND "+s.status()+"=?";args.add(status);}if(store!=null&&s.store()!=null){where+=s.store().equals("EXISTS_ORDER")?" AND EXISTS(SELECT 1 FROM ORDER_ITEMS i WHERE i.order_id=t.id AND i.store_id=?)":" AND "+s.store()+"=?";args.add(store);}
  if(area.equals("users")&&!role.isBlank()){where+=" AND EXISTS(SELECT 1 FROM USER_ROLES ur JOIN ROLES r ON r.id=ur.role_id WHERE ur.user_email=t.email AND r.name=?)";args.add(role);}
  if(area.equals("orders")){if(!method.isBlank()){where+=" AND t.payment_method=?";args.add(method);}if(!paymentStatus.isBlank()){where+=" AND p.status=?";args.add(paymentStatus);}}
  if(area.equals("catalog-requests")&&!requestType.isBlank()){where+=" AND t.request_type=?";args.add(requestType);}
  String dateColumn=Set.of("promotions","coupons").contains(area)?"t.starts_at":"t.created_at";
  if(!Set.of("users","inventory","variants").contains(area)){if(!fromDate.isBlank()){where+=" AND "+dateColumn+">=?";args.add(java.time.LocalDate.parse(fromDate).atStartOfDay());}if(!toDate.isBlank()){where+=" AND "+dateColumn+"<?";args.add(java.time.LocalDate.parse(toDate).plusDays(1).atStartOfDay());}}
  long total=sql.queryForObject("SELECT COUNT_BIG(*) FROM "+s.from()+where,Long.class,args.toArray());String order=s.key();if(sort.equals("name")&&Set.of("stores","brands","categories","products","promotions","coupons").contains(area))order="t.name,"+s.key();else if(sort.equals("quantity")&&area.equals("inventory"))order="t.quantity,t.store_id,t.variant_id";
  Set<String> sorting=switch(area){case "users"->Set.of("email","full_name","is_enabled","created_at","updated_at");case "stores"->Set.of("name","manager_email","status","city","inventory_count","order_count");case "products"->Set.of("name","brand","category","base_price","status","variant_count","store_count","updated_at");case "variants"->Set.of("sku","product","size","color","price_adjustment","status","inventory_count");case "inventory"->Set.of("store","product","sku","quantity","reorder_level","status","pending_requests");case "orders"->Set.of("order_code","user_email","status","payment_method","payment_status","total","created_at");case "catalog-requests"->Set.of("store","request_type","status","created_at","requester_email");case "restock-requests"->Set.of("store","sku","requested_quantity","status","created_at");case "inventory-movements"->Set.of("store","sku","new_quantity","quantity_delta","created_at");case "promotions"->Set.of("name","discount_value","scope","priority","status","starts_at","ends_at");case "coupons"->Set.of("code","name","used_count","usage_limit","per_user_limit","is_active");case "categories"->Set.of("name","slug","status","product_count");case "brands"->Set.of("name","slug","product_count");default->Set.of();};
  String ordering=sorting.contains(sort)?"["+sort+"]"+(direction.equalsIgnoreCase("asc")?" ASC":" DESC")+","+s.key()+" ASC":order+(direction.equalsIgnoreCase("asc")?" ASC":" DESC");
  args.add(Math.multiplyExact(page,size));args.add(size);var rows=sql.queryForList("SELECT "+s.select()+" FROM "+s.from()+where+" ORDER BY "+ordering+" OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",args.toArray());if(area.equals("products")){var prices=pricing.calculateEffectivePricesBatch(products.findByIdIn(rows.stream().map(r->((Number)r.get("id")).intValue()).toList()),LocalDateTime.now());rows.forEach(r->r.put("effective_price",prices.get(((Number)r.get("id")).intValue())));}if(area.equals("inventory")) rows.forEach(r -> cyan.project.twinkle.service.StockPresentation.enrich(r,true));return new Page(rows,total,page,size);
 }
 public Map<String,Object> detail(String area,String id){context.actor();var s=source(area);if(area.equals("inventory"))throw new IllegalArgumentException();var rows=sql.queryForList("SELECT "+s.select()+" FROM "+s.from()+" WHERE "+s.key()+"=?",id);if(rows.isEmpty())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND);var result=rows.getFirst();
  if(area.equals("users")){result.put("support_store_ids",sql.queryForList("SELECT store_id FROM STORE_STAFF_ASSIGNMENTS WHERE user_email=? AND active=1 ORDER BY store_id",Integer.class,id));result.put("support_stores",sql.queryForList("SELECT s.store_id AS id,s.name FROM STORE_STAFF_ASSIGNMENTS a JOIN STORES s ON s.store_id=a.store_id WHERE a.user_email=? AND a.active=1 ORDER BY s.name,s.store_id",id));}
  if(area.equals("orders")){
   result.put("refunds",sql.queryForList("SELECT status,amount,processed_at FROM PAYMENT_REFUNDS WHERE order_id=?",id));
   result.put("items",sql.queryForList("SELECT * FROM ORDER_ITEMS WHERE order_id=? ORDER BY id",id));
   // Checkout fulfillment rows are provisioned lazily under the existing order lock.
   // Display every participating store before that first transition without mutating an order on GET.
   result.put("fulfillments",sql.queryForList("SELECT f.id,scope.order_id,scope.store_id,COALESCE(f.status,o.status) AS status,f.confirmed_at,f.delivered_at,f.cancelled_at,f.updated_by,f.updated_at,s.name AS store FROM (SELECT DISTINCT order_id,store_id FROM ORDER_ITEMS WHERE order_id=?) scope JOIN ORDERS o ON o.id=scope.order_id JOIN STORES s ON s.store_id=scope.store_id LEFT JOIN ORDER_STORE_FULFILLMENTS f ON f.order_id=scope.order_id AND f.store_id=scope.store_id ORDER BY scope.store_id",id));
   result.put("history",sql.queryForList("SELECT status,note,created_at FROM ORDER_STATUS_HISTORY WHERE order_id=? ORDER BY id",id));
   result.put("cancellation",sql.queryForList("SELECT reason,other_reason,status,response_note FROM ORDER_CANCELLATIONS WHERE order_id=?",id));
   result.put("payment",sql.queryForList("SELECT id,amount,method,status,paid_at FROM PAYMENTS WHERE order_id=?",id));
  }
  if(area.equals("products")){result.put("images",sql.queryForList("SELECT * FROM PRODUCT_IMAGES WHERE product_id=? ORDER BY sort_order,id",id));result.put("variants",sql.queryForList("SELECT * FROM PRODUCT_VARIANTS WHERE product_id=? ORDER BY id",id));result.put("effective_price",pricing.calculateEffectivePrice(products.findById(Integer.valueOf(id)).orElseThrow(),LocalDateTime.now()));}
  if(area.equals("promotions")){String scope=(String)result.get("scope");result.put("targets",scope.equals("GLOBAL")?List.of():sql.queryForList("SELECT "+AdminPromotionService.targetColumn(scope)+" FROM "+AdminPromotionService.targetTable(scope)+" WHERE promotion_id=?",Long.class,id));}return result;
 }
 public List<Map<String,Object>> options(String kind,String search){context.actor();if(search.length()>150)throw new IllegalArgumentException();return switch(kind){case "roles"->sql.queryForList("SELECT id,name FROM ROLES WHERE name IN('ROLE_USER','ROLE_MANAGER','ROLE_SUPPORT','ROLE_ADMIN') ORDER BY id");case "stores"->sql.queryForList("SELECT TOP(100) store_id AS id,name FROM STORES WHERE name LIKE ? ORDER BY name","%"+search+"%");case "managers"->sql.queryForList("SELECT TOP(100) u.email AS id,u.email AS name FROM USERS u JOIN USER_ROLES ur ON ur.user_email=u.email JOIN ROLES r ON r.id=ur.role_id WHERE r.name='ROLE_MANAGER' AND u.is_enabled=1 AND u.email LIKE ? ORDER BY u.email","%"+search+"%");case "categories","brands","products"->{String table=switch(kind){case "categories"->"CATEGORIES";case "brands"->"BRANDS";default->"PRODUCTS";};yield sql.queryForList("SELECT TOP(100) id,name FROM "+table+" WHERE name LIKE ? ORDER BY name,id","%"+search+"%");}case "variants"->sql.queryForList("SELECT TOP(100) id,sku AS name FROM PRODUCT_VARIANTS WHERE sku LIKE ? ORDER BY sku","%"+search+"%");default->throw new IllegalArgumentException();};}
}

